// Package notify delivers best-effort webhook notifications for project
// state transitions a human should hear about (quota waits, blocks, goal
// completion). It is a no-op unless GOALFORGE_WEBHOOK_URL is set.
package notify

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"time"

	"github.com/goalforge/goalforge/internal/audit"
)

// EnvWebhookURL configures the JSON webhook endpoint.
const EnvWebhookURL = "GOALFORGE_WEBHOOK_URL"

// Event describes a state transition. Text doubles as a Slack-compatible
// message body; when empty it is derived from the other fields.
type Event struct {
	Project string `json:"project"`
	// Name is what a person calls the project. A webhook that says
	// "PRJ-1790493808621901102" makes the reader look it up before they can
	// tell whether it concerns them.
	Name   string `json:"name,omitempty"`
	State  string `json:"state"`
	Reason string `json:"reason,omitempty"`
	Text   string `json:"text"`
}

// label is the project as a person would refer to it.
func (e Event) label() string {
	if e.Name != "" {
		return e.Name
	}
	return e.Project
}

// Post sends event to the configured webhook. It is best-effort: an unset
// URL is a no-op, secrets are redacted, and callers are expected to ignore
// the returned error rather than fail the transition that triggered it.
func Post(ctx context.Context, event Event) error {
	url := os.Getenv(EnvWebhookURL)
	if url == "" {
		return nil
	}
	event.Reason = audit.RedactString(event.Reason)
	// The same block repeated on every worker tick trains people to ignore the
	// channel, so an identical event stays quiet for a window. A changed
	// reason is news and always goes through.
	if !defaultSuppressor.allow(event.Project+"\x00"+event.State+"\x00"+event.Reason, repeatWindow()) {
		return nil
	}
	if event.Text == "" {
		event.Text = fmt.Sprintf("GoalForge %s: project %s", event.State, event.label())
		if event.Reason != "" {
			event.Text += " — " + event.Reason
		}
	} else {
		event.Text = audit.RedactString(event.Text)
	}
	body, err := json.Marshal(event)
	if err != nil {
		return err
	}
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(body))
	if err != nil {
		return err
	}
	request.Header.Set("Content-Type", "application/json")
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	_, _ = io.Copy(io.Discard, response.Body)
	if response.StatusCode >= 300 {
		return fmt.Errorf("webhook returned status %d", response.StatusCode)
	}
	return nil
}
package notify

import (
	"os"
	"sync"
	"time"
)

// EnvRepeatWindow overrides how long an identical notification is suppressed.
const EnvRepeatWindow = "GOALFORGE_WEBHOOK_REPEAT_WINDOW"

// defaultRepeatWindow is how long the same project/state/reason stays quiet.
// A blocked project re-reports its block on every worker tick; without a
// window the webhook becomes noise people learn to ignore, which is worse
// than no webhook at all.
const defaultRepeatWindow = 30 * time.Minute

type suppressor struct {
	mu   sync.Mutex
	seen map[string]time.Time
	now  func() time.Time
}

var defaultSuppressor = &suppressor{seen: map[string]time.Time{}, now: time.Now}

// allow reports whether an event should be sent, recording it when it is.
// Repeats of the same project, state, and reason inside the window are
// dropped; a changed reason is always news and goes through.
func (s *suppressor) allow(key string, window time.Duration) bool {
	if window <= 0 {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	if last, ok := s.seen[key]; ok && now.Sub(last) < window {
		return false
	}
	// Entries older than the window can never suppress anything again, so
	// they are dropped rather than growing the map for the process lifetime.
	for existing, at := range s.seen {
		if now.Sub(at) >= window {
			delete(s.seen, existing)
		}
	}
	s.seen[key] = now
	return true
}

func repeatWindow() time.Duration {
	if value := os.Getenv(EnvRepeatWindow); value != "" {
		parsed, err := time.ParseDuration(value)
		if err == nil && parsed >= 0 {
			return parsed
		}
	}
	return defaultRepeatWindow
}
package notify

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestPostSendsRedactedSlackCompatiblePayload(t *testing.T) {
	var received Event
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		if r.Header.Get("Content-Type") != "application/json" {
			t.Errorf("content type %q", r.Header.Get("Content-Type"))
		}
		if err := json.Unmarshal(body, &received); err != nil {
			t.Errorf("decode payload: %v", err)
		}
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()
	t.Setenv(EnvWebhookURL, server.URL)
	err := Post(context.Background(), Event{Project: "P1", State: "WAITING_QUOTA", Reason: "api_key=sk-abc123 quota exhausted"})
	if err != nil {
		t.Fatal(err)
	}
	if received.Project != "P1" || received.State != "WAITING_QUOTA" {
		t.Fatalf("payload=%+v", received)
	}
	if strings.Contains(received.Reason, "sk-abc123") || strings.Contains(received.Text, "sk-abc123") {
		t.Fatalf("secret leaked into payload: %+v", received)
	}
	if !strings.Contains(received.Text, "GoalForge WAITING_QUOTA") || !strings.Contains(received.Text, "P1") {
		t.Fatalf("text=%q", received.Text)
	}
}

func TestPostIsNoOpWithoutURLAndSurfacesServerErrors(t *testing.T) {
	t.Setenv(EnvWebhookURL, "")
	if err := Post(context.Background(), Event{Project: "P1", State: "BLOCKED"}); err != nil {
		t.Fatalf("unset URL must be a no-op: %v", err)
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
	}))
	defer server.Close()
	t.Setenv(EnvWebhookURL, server.URL)
	if err := Post(context.Background(), Event{Project: "P1", State: "BLOCKED"}); err == nil {
		t.Fatal("expected error for 500 response")
	}
}
package notify

import (
	"testing"
	"time"
)

// A blocked project re-reports its block on every worker tick. Without a
// window the webhook becomes noise people learn to ignore, which is worse than
// no webhook at all.
func TestSuppressorDropsRepeatsWithinTheWindow(t *testing.T) {
	now := time.Date(2026, 9, 27, 9, 0, 0, 0, time.UTC)
	s := &suppressor{seen: map[string]time.Time{}, now: func() time.Time { return now }}
	window := 30 * time.Minute
	if !s.allow("p|BLOCKED|loop", window) {
		t.Fatal("the first notification must go through")
	}
	if s.allow("p|BLOCKED|loop", window) {
		t.Fatal("an identical repeat must be suppressed")
	}
	// A different reason is news even for the same project and state.
	if !s.allow("p|BLOCKED|quota", window) {
		t.Fatal("a changed reason must go through")
	}
	now = now.Add(window + time.Second)
	if !s.allow("p|BLOCKED|loop", window) {
		t.Fatal("the same event must be reportable again after the window")
	}
	// Expired entries are dropped rather than growing for the process lifetime.
	if len(s.seen) != 1 {
		t.Fatalf("expired keys should be pruned, have %d", len(s.seen))
	}
}

// A zero window disables suppression entirely, which is what an operator
// setting the window to 0 is asking for.
func TestSuppressorWindowZeroAllowsEverything(t *testing.T) {
	s := &suppressor{seen: map[string]time.Time{}, now: time.Now}
	for i := 0; i < 3; i++ {
		if !s.allow("p|BLOCKED|loop", 0) {
			t.Fatal("a zero window must not suppress")
		}
	}
}

func TestEventLabelPrefersTheName(t *testing.T) {
	if got := (Event{Project: "PRJ-1", Name: "checkout"}).label(); got != "checkout" {
		t.Fatalf("label=%q", got)
	}
	if got := (Event{Project: "PRJ-1"}).label(); got != "PRJ-1" {
		t.Fatalf("label=%q", got)
	}
}
